exercises.starter_code:
SELECT ville, COUNT(*) AS nombre_membres
FROM membres GROUP BY ville HAVING COUNT(*) > 2
ORDER BY nombre_membres DESC, ville ASC;

SELECT ville, COUNT(*) AS participants, MIN(age) AS age_min
FROM membres GROUP BY ville HAVING COUNT(*) >= 2
ORDER BY participants DESC, ville ASC;

SELECT prix, SUM(places) AS places_totales, COUNT(*) AS nombre_ateliers
FROM ateliers GROUP BY prix HAVING COUNT(*) >= 5
ORDER BY places_totales DESC, prix ASC;

SELECT statut, COUNT(*) AS nombre
FROM inscriptions GROUP BY statut HAVING COUNT(*) >= 2
ORDER BY nombre DESC, statut ASC;

SELECT i.id AS inscription_id, m.nom AS membre
FROM inscriptions AS i INNER JOIN membres AS m ON i.id = m.id
ORDER BY i.id ASC;

SELECT i.id AS inscription_id, a.titre AS atelier
FROM inscriptions AS i INNER JOIN ateliers AS a ON i.atelier_id = a.id
WHERE i.statut = 'confirmee' ORDER BY i.id ASC;

SELECT m.id AS membre_id, m.nom AS membre, i.id AS inscription_id
FROM membres AS m INNER JOIN inscriptions AS i ON i.membre_id = m.id
WHERE m.ville <> NULL ORDER BY m.id ASC, i.id ASC;

SELECT m.id AS membre_id, m.nom AS membre, i.id AS inscription_id
FROM membres AS m INNER JOIN inscriptions AS i ON i.membre_id = m.id
ORDER BY m.id ASC, i.id ASC;

SELECT a.id AS atelier_id, a.titre AS atelier, COUNT(*) AS total_inscriptions
FROM ateliers AS a LEFT JOIN inscriptions AS i ON i.atelier_id = a.id
GROUP BY a.id,a.titre ORDER BY a.id ASC;

SELECT m.id AS membre_id, m.nom AS membre
FROM membres AS m LEFT JOIN inscriptions AS i ON i.membre_id = m.id
WHERE i.id = NULL ORDER BY m.id ASC;

