-- Deux structures reliées, sans écriture de données.
CREATE TABLE genres(id INTEGER PRIMARY KEY, nom TEXT NOT NULL UNIQUE);
CREATE TABLE livres(id INTEGER PRIMARY KEY, titre TEXT NOT NULL, genre_id INTEGER NOT NULL REFERENCES genres(id));

-- Ajouter une fiche fictive avec des colonnes explicites.
INSERT INTO membres(id,nom,ville,age) VALUES(10,'Ama','Atakpamé',18);
SELECT id,nom,age FROM membres WHERE id=10;

-- Doubler une apostrophe à l’intérieur du texte SQL.
INSERT INTO ateliers(id,titre,places,prix) VALUES(10,'Club d''art',2,500);
SELECT id,titre,prix FROM ateliers WHERE id=10;

-- Une augmentation sur un atelier identifié.
UPDATE ateliers SET places = places + 1 WHERE id = 1;
SELECT id,places FROM ateliers WHERE id=1;

-- Retirer uniquement les demandes en attente.
DELETE FROM inscriptions WHERE statut = 'attente';
SELECT id,statut FROM inscriptions ORDER BY id;

-- Validation explicite dans la base de cet essai.
BEGIN;
UPDATE ateliers SET places=places+1 WHERE id=1;
COMMIT;
SELECT id,places FROM ateliers WHERE id=1;

-- Trois observations : avant, provisoire, restauré.
BEGIN;
SELECT id,places FROM ateliers WHERE id=1 ORDER BY id;
UPDATE ateliers SET places = places + 3 WHERE id=1;
SELECT id,places FROM ateliers WHERE id=1 ORDER BY id;
ROLLBACK;
SELECT id,places FROM ateliers WHERE id=1 ORDER BY id;

